type Scenario={body:OperatingPlanBody;evaluation:OperatingEvaluation;goal:OperatingGoalRead;guidance:OperatingGuidance;evidence:OperatingEvidence;handoff:Record<string,unknown>|null};
function merge(base:unknown,patch:unknown):unknown {if(!patch||typeof patch!=="object"||Array.isArray(patch))return patch;const value={...(base&&typeof base==="object"?base as Record<string,unknown>:{})};for(const[key,item]of Object.entries(patch as Record<string,unknown>))value[key]=merge(value[key],item);return value;}
export function planGoalsScenario(name:PlanGoalsCase="compact"):Scenario{return structuredClone(merge(encoded.compact,encoded[name])) as Scenario;}
export function planGoalsInitial(name:PlanGoalsCase="compact"){return planGoalsScenario(name).body;}
export function planGoalsSnapshot(body:OperatingPlanBody,revision:number,name:PlanGoalsCase="compact"):FinancialWorkspaceSnapshot{const base=operatingEditSnapshot(body,revision),scenario=planGoalsScenario(name);return{...base,evidence:(scenario.evidence.files??[]).map(row=>({...row,content_type:"application/pdf"})),completion:base.completion?{...base.completion,released_cash_flow:scenario.evaluation.released_cash_flow}:base.completion};}
